#!/bin/bash
# c3-outline.sh (2026-11-02): the Cortex outline typed into the Cortex brain through the front door (handler section 5), so the brain holds it.
export PATH=$HOME/.local/bin:$PATH
set -e
cortex project cortex : "cortex is the persistent cognitive memory for llms on hp2. it holds every project's scope, outline, ingests and verdicts as lines in the nk brain; judges each ingest against the current state with jev and the brain's geometry; keeps the outline as satisfied checkpoints; and hydrates one-turn workers so their whole context is the hydration, which is the blink."
cortex checkpoint cortex 0 : "nk built from the copied source on hp2; a fresh brain on its own file; the socket answers" "||" "stats over the socket on hp2 returns the egg's symbols; a typed line returns a run id and the clock advances"
cortex checkpoint cortex 1 : "the brain educated: the kernel's own line files replayed in the order hp's ledgers show, with the full sources attached" "||" "define : cortex returns definitions from wn and gcide; asked again it recalls with no source asked"
cortex checkpoint cortex 2 : "front door cortex ingest and cortex status; the keyed index main.cx, because the kernel refuses every read without a key" "||" "an ingest returns its run id and clock; the same sentence again is a repeat the brain or the index can show"
cortex checkpoint cortex 3 : "this outline in the brain: every checkpoint and expected output typed as cortex lines; cortex hydrate reads them back from the brain" "||" "the hydration lists the checkpoints c0 to c9 with states read from the index, not from the handler file"
cortex checkpoint cortex 4 : "cortex judge: geometry of the ingest's placed words against the scope's placed words, and jev when the key is present; the truth table in code; a verdict line typed" "||" "an on-scope ingest and an off-scope one get different verdict lines in the brain with probabilities shown; with no key the verdict names geometry as its judge"
cortex checkpoint cortex 5 : "cortex turn: hydrate, one worker turn, ingest its output, judge, move the checkpoint, the next hydration" "||" "one live turn on hp2: the worker's prompt byte count equals the hydration's; the output's verdict moved a state; the next hydration differs by that state"
cortex checkpoint cortex 6 : "the neuron project registered as the second project: scope from the archive's specs current note authority order, checkpoints from the 10-31 review's gates 0 to 3" "||" "cortex hydrate neuron prints the neuron rail from the brain"
cortex checkpoint cortex 7 : "the router: a step marked judgment goes to jev never to a model; model by step kind" "||" "a turn's receipt shows a judgment step answered by jev with no claude or codex process started"
cortex checkpoint cortex 8 : "freeze: the handler file read-only, its sha typed as cortex freeze, cortex status compares" "||" "cortex status prints both shas equal; a write to the file fails"
cortex checkpoint cortex 9 : "the hub reaches cortex with a config line only" "||" "ssh hp2 cortex hydrate cortex from the hub prints the hydration; no cortex file on the hub"
cortex state cortex 0 done
cortex state cortex 1 done
cortex state cortex 2 done
cortex state cortex 3 working
echo "=== hydrate"; cortex hydrate cortex
echo "=== status"; cortex status cortex
